INSERT INTO agent_invoice_extraction_run(id,tenant_id,invoice_id,owner_id,original_id,original_digest,
    original_format,original_bytes,page_count,method,target_digest,status,version,context_json,state_json,created_at,active_invoice_id,trace_id)
SELECT #{id},tenant_id,invoice_id,owner_id,id,sha256,format,byte_size,#{pageCount},#{method},#{targetDigest},'QUEUED',1,#{stateJson},#{stateJson2},#{createdAt},invoice_id,#{traceId}
FROM invoice_original WHERE tenant_id=#{tenantId} AND invoice_id=#{invoiceId} AND owner_id=#{requestedBy} AND id=#{originalId} AND sha256=#{originalDigest}
    AND format=#{format} AND byte_size=#{originalBytes} AND status='READY'
